import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Device Hardening — Claude 5 Security Pass Prompt","description":"","frontmatter":{"url":"https://x.com/Truunik/status/2064399110384292077","title":"Device Hardening — Claude 5 Security Pass Prompt","author":"Truu","archived":"2026-06-13T00:00:00.000Z","handle":"@Truunik","published":"2026-06-09T00:00:00.000Z","stats":"28 likes · 3 retweets · 27 bookmarks · 4310 views","tags":["security","device-hardening","prompt-template","defensive-security","claude-fable-5"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-09-@Truunik-292077.md","filePath":"research/tweets/2026-06-09-@Truunik-292077.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-06-09-@Truunik-292077.md"};function i(n,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="device-hardening-—-claude-5-security-pass-prompt-—-truunik" tabindex="-1">Device Hardening — Claude 5 Security Pass Prompt — @Truunik <a class="header-anchor" href="#device-hardening-—-claude-5-security-pass-prompt-—-truunik" aria-label="Permalink to &quot;Device Hardening — Claude 5 Security Pass Prompt — @Truunik&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/Truunik/status/2064399110384292077" target="_blank" rel="noreferrer">https://x.com/Truunik/status/2064399110384292077</a><strong>作者</strong>：Truu（@Truunik） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-13 <strong>類型</strong>：Tweet <strong>統計</strong>：28 likes · 3 retweets · 27 bookmarks · 4310 views</p><blockquote><p>Quote @claudeai: Introducing Claude Fable 5: a Mythos-class model that we&#39;ve made safe for general use. Its capabilities exceed those of any model we&#39;ve ever made generally available.</p></blockquote><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>&quot;Safe for general use&quot;</p><p>here&#39;s a prompt to secure your devices : ( works with opus 4.8 and Fable 5 )</p><p>DEVICE HARDENING — Claude 5 Security Pass</p><p>You are acting as a defensive security assistant. Your job is to walk me through hardening ALL of my devices and verify each step. This is authorized self-defense hardening of devices I own.</p><p>STEP 0 — MODEL SELF-CHECK (do this first, set a flag)</p><ol><li>State your exact model ID (e.g. claude-opus-4-8, claude-fable-5, claude-mythos-5).</li><li>Decide: is this model in the Claude 5 family (Fable 5 / Mythos 5)? <ul><li>If YES, set RERUN_NOTICE = false.</li><li>If NO (e.g. Opus 4.8 or earlier), set RERUN_NOTICE = true. Continue the full hardening pass normally. Do NOT stop or degrade. You are fully capable of this defensive task.</li></ul></li><li>Surface the flag only in the FINAL section.</li></ol><p>STEP 1 — INVENTORY Ask me which devices are in scope: laptops/desktops (and OS), phones/tablets, routers, NAS/home server, and always-on accounts (Apple ID, Google, Microsoft, GitHub, password manager, email, financial). Produce a short numbered inventory and confirm with me before proceeding.</p><p>STEP 2 — HARDENING WALKTHROUGH Go category by category. For EACH item: (a) say what to do, (b) give the exact command or settings path for MY OS, (c) tell me how to VERIFY it&#39;s done, (d) wait for me to confirm before moving on. Never run a destructive command without explicit confirmation; prefer read-only checks and let me apply changes.</p><p>Cover, in order:</p><ol><li>OS &amp; firmware updates — fully patched OS, automatic updates on, firmware current.</li><li>Disk encryption — FileVault / BitLocker / LUKS enabled; recovery key stored offline.</li><li>Account auth — unique strong passwords via a password manager; phishing-resistant MFA (passkeys / hardware keys) on every critical account; remove SMS-only 2FA where possible; review and revoke stale sessions and app tokens.</li><li>Local accounts &amp; privileges — separate admin vs daily-use account; no auto-login; screen lock with short timeout; firmware/login password.</li><li>Network — firewall on; router admin password changed, firmware updated, WPA3, remote admin off, UPnP reviewed; DNS hardening; guest network for IoT.</li><li>App &amp; permission audit — review camera/mic/location/screen-recording/full-disk-access grants; remove unused apps; check login items and background agents.</li><li>Browser — update, audit extensions (remove unknown ones), enable HTTPS-only, review saved-password exposure, check for unknown sync devices.</li><li>Backups — encrypted, automated, 3-2-1 rule, one copy offline; verify a restore actually works.</li><li>Credential hygiene — scan for plaintext secrets in dotfiles / env files / shell history; confirm sensitive files are locked down; rotate anything exposed.</li><li>Mobile devices — OS current, biometric + strong passcode, lockdown/advanced-protection mode if available, app permission sweep, find-my enabled.</li><li>Compromise check — look for unknown SSH keys, unexpected admin users, suspicious launch agents/cron, unrecognized logged-in sessions or devices.</li></ol><p>STEP 3 — REPORT Produce a checklist of every item marked done / needs action / skipped, with the top 3 highest-impact actions still outstanding.</p><p>FINAL — RERUN NOTICE If RERUN_NOTICE == true, end with EXACTLY this: NOTICE: This hardening pass ran on a pre–Claude 5 model (your model ID). It is complete and valid, but Claude 5 (Fable 5 / Mythos 5) has stronger security reasoning. Re-run this prompt on Claude 5 as soon as possible to catch anything this pass may have missed.</p><p>If RERUN_NOTICE == false, end with: Hardening pass completed on Claude 5. No re-run needed.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：結構化的個人裝置防護 prompt，涵蓋 11 類安全加固步驟（OS patch→加密→MFA→網路→憑證清理→入侵檢查），含模型版本自檢與驗證流程。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>互動式引導</strong>：每個步驟要求 (a) 指令 (b) 對應 OS 的具體路徑/命令 (c) 驗證方式 (d) 用戶確認，強制 human-in-the-loop</li><li><strong>模型自檢機制</strong>：STEP 0 讓模型自報 ID 並設 flag，非 Claude 5 家族時尾部附加 RERUN_NOTICE</li><li><strong>全面涵蓋</strong>：從韌體更新到 SSH key 審計、cron 異常偵測，接近 CIS Benchmark 個人版</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>11 個加固類別（OS/加密/帳號/權限/網路/App/瀏覽器/備份/憑證/行動裝置/入侵檢查）</li><li>適用模型：Opus 4.8、Fable 5</li><li>技術：FileVault/BitLocker/LUKS、passkeys/hardware keys、WPA3、3-2-1 備份</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>實用但非創新</strong>：內容是標準安全加固清單的 prompt 化，對安全從業者無新意，但對一般用戶有操作指引價值</li><li><strong>模型自檢設計有趣</strong>：RERUN_NOTICE flag 是一個 prompt engineering pattern（模型能力自評 + 條件式輸出），但模型 ID 自報不可靠（可被 system prompt 覆蓋）</li><li><strong>與 workspace 關聯低</strong>：為個人裝置安全，非 codebase/infra 層面；但 credential hygiene（Step 9）的 dotfiles/env scan 可對照 security-hygiene.md</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>3/10</td><td>個人裝置加固，非 codebase/infra 場景；credential scan 有微弱關聯</td></tr><tr><td>B. 創新性 (20%)</td><td>4/10</td><td>標準安全清單的 prompt 化；RERUN_NOTICE flag 模式有一定新意</td></tr><tr><td>C. 證據品質 (20%)</td><td>4/10</td><td>純指令模板，無實測數據或效果驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>涵蓋面廣但每項深度有限，偏 checklist 而非原理</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>對任何人的個人安全維護有通用價值</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.05/10</strong></td><td>3×0.3+4×0.2+4×0.2+5×0.15+6×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：個人裝置安全 checklist，與 workspace 的 codebase/infra 安全場景不直接相關</p>',31)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
